def has_pair_with_sum(numbers, target):
    """True if two different positions in ``numbers`` add up to ``target``."""
    for i in range(len(numbers)):
        for j in range(len(numbers)):
            if i != j and numbers[i] + numbers[j] == target:
                return True
    return False

